it.each(currentPublished)('authenticates entire current %s and its original publication', (path, imported, beforeHash)=>{
 const text=readFileSync(new URL('../../../'+path,import.meta.url),'utf8').replace(/\r\n/g,'\n');
 expect(imported).toEqual(JSON.parse(text));
 const original=lv3AfterUnitPublishedText('LV3-U15',path,text);
 expect(createHash('sha256').update(original).digest('hex')).toBe(beforeHash);
});
it('keeps the complete installed U16 current and rejects mutated or incomplete callers',()=>{
 const current=JSON.parse(readFileSync(new URL('./curriculumLV3Unit16.json',import.meta.url),'utf8'));
 expect(unit.items).toEqual(current.learningItems);
 expect(unit.items).toHaveLength(192);
 expect(unit.items.filter(i=>i.kind==='vocabulary')).toHaveLength(134);
 expect(unit.items.filter(i=>i.kind==='grammar')).toHaveLength(58);
 const mapped=unit.items.filter(i=>i.kind==='vocabulary'&&i.officialWordId);
 expect(mapped).toHaveLength(96);expect(new Set(mapped.map(i=>i.officialWordId)).size).toBe(95);
 expect(unit.items.filter(i=>i.kind==='vocabulary'&&!i.officialWordId)).toHaveLength(38);
 const changed=structuredClone(unit.items);changed[0].targetMeaningZh='unrecorded';
 expect(()=>originalUnit16Items(changed)).toThrow(/Installed U16 items differ/);
 expect(()=>originalUnit16Items(unit.items.slice(1))).toThrow(/Installed U16 items differ/);
 expect(()=>originalUnit16Items([...unit.items].reverse())).toThrow(/Installed U16 items differ/);
});
it('rejects unknown current U16 publication bytes and content before historical projection',()=>{
 const path='src/features/direct/curriculumLV3Unit16.json';
 const text=readFileSync(new URL('./curriculumLV3Unit16.json',import.meta.url),'utf8');
 expect(()=>lv3AfterUnitPublishedText('LV3-U15',path,text+' ')).toThrow();
 expect(()=>lv3AfterUnitPublishedText('LV3-U15',path,JSON.stringify({...JSON.parse(text),unrecorded:true})+'\n')).toThrow();
});

